/**
 * Rateio de valores monetários em centavos.
 *
 * allocate(totalCents, weights) divide `totalCents` em partes inteiras
 * proporcionais a `weights`, sem perder nem criar centavos (a soma das partes
 * é sempre `totalCents`).
 *
 * Método do maior resto:
 *   1. cada parte recebe floor(totalCents * w / soma(weights));
 *   2. os centavos que sobram são entregues, um por parte, às partes com maior
 *      resto da divisão; em caso de empate no resto, a parte de menor índice
 *      recebe primeiro.
 */

function assertInt(name, value) {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative integer, got ${value}`);
  }
}

export function allocate(totalCents, weights) {
  assertInt('totalCents', totalCents);
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a non-empty array');
  }
  weights.forEach((w, i) => assertInt(`weights[${i}]`, w));
  const sum = weights.reduce((acc, w) => acc + BigInt(w), 0n);
  if (sum === 0n) throw new RangeError('weights must not all be zero');

  const total = BigInt(totalCents);
  const parts = weights.map((w, index) => {
    const scaled = total * BigInt(w);
    const base = scaled / sum;
    return { index, amount: base, remainder: scaled - base * sum };
  });

  let leftover = Number(total - parts.reduce((acc, p) => acc + p.amount, 0n));
  const byRemainder = [...parts].sort((x, y) => {
    if (x.remainder !== y.remainder) return x.remainder < y.remainder ? 1 : -1;
    return x.index - y.index;
  });
  for (let i = 0; leftover > 0; i++, leftover--) {
    byRemainder[i].amount += 1n;
  }
  return parts.map((p) => Number(p.amount));
}

/**
 * Divide `totalCents` em `n` partes iguais (diferença máxima de 1 centavo).
 */
export function splitEvenly(totalCents, n) {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer');
  return allocate(totalCents, new Array(n).fill(1));
}

